import * as fs from 'node:fs';
import * as path from 'node:path';

export interface TranscriptEntry {
  audioFile: string;
  transcribed: boolean;
  refinedByLLM: boolean;
  /** Name of the refined text file in processed/, e.g. "voice_....refined.txt". */
  refinedTextFile?: string;
  /** Short title generated by the LLM. */
  title?: string;
  /** Short tags generated by the LLM (in the text's language). */
  tags?: string[];
  /** Small summary used by other LLMs to find this note. */
  resume?: string;
}

export interface RefinedData {
  refinedTextFile: string;
  title: string;
  tags: string[];
  resume: string;
}

/**
 * File-backed repository for the transcripts database (transcripts.json).
 * The JSON is an array of entries: { audioFile, transcribed, refinedByLLM }
 * plus the optional LLM refinement metadata (title, tags, resume, refinedTextFile).
 */
export class TranscriptsDb {
  private readonly entries = new Map<string, TranscriptEntry>();

  constructor(private readonly filePath: string) {}

  load(): void {
    if (!fs.existsSync(this.filePath)) return;
    const raw = JSON.parse(fs.readFileSync(this.filePath, 'utf8')) as unknown;
    if (!Array.isArray(raw)) {
      throw new Error(`Transcripts database ${this.filePath} must be a JSON array`);
    }
    for (const item of raw as Array<Partial<TranscriptEntry>>) {
      if (typeof item.audioFile !== 'string') continue;
      const entry: TranscriptEntry = {
        audioFile: item.audioFile,
        transcribed: item.transcribed === true,
        refinedByLLM: item.refinedByLLM === true,
      };
      if (typeof item.refinedTextFile === 'string') entry.refinedTextFile = item.refinedTextFile;
      if (typeof item.title === 'string') entry.title = item.title;
      if (Array.isArray(item.tags)) {
        entry.tags = item.tags.filter((tag): tag is string => typeof tag === 'string');
      }
      if (typeof item.resume === 'string') entry.resume = item.resume;
      this.entries.set(item.audioFile, entry);
    }
  }

  save(): void {
    fs.mkdirSync(path.dirname(this.filePath), { recursive: true });
    fs.writeFileSync(
      this.filePath,
      JSON.stringify([...this.entries.values()], null, 2) + '\n',
      'utf8',
    );
  }

  get(audioFile: string): TranscriptEntry | undefined {
    return this.entries.get(audioFile);
  }

  all(): TranscriptEntry[] {
    return [...this.entries.values()];
  }

  markCopied(audioFile: string): void {
    const existing = this.entries.get(audioFile);
    this.entries.set(audioFile, existing ?? { audioFile, transcribed: false, refinedByLLM: false });
  }

  markTranscribed(audioFile: string): void {
    const existing = this.entries.get(audioFile) ?? {
      audioFile,
      transcribed: false,
      refinedByLLM: false,
    };
    this.entries.set(audioFile, { ...existing, transcribed: true });
  }

  /**
   * Records the LLM refinement result, preserving every other field (notably
   * `transcribed`) and flipping `refinedByLLM`.
   */
  markRefined(audioFile: string, data: RefinedData): void {
    const existing = this.entries.get(audioFile) ?? {
      audioFile,
      transcribed: false,
      refinedByLLM: false,
    };
    this.entries.set(audioFile, {
      ...existing,
      refinedByLLM: true,
      refinedTextFile: data.refinedTextFile,
      title: data.title,
      tags: data.tags,
      resume: data.resume,
    });
  }
}
